function normaliseWeather(value){const source=value?.weather||value||{},temperatureC=weatherNumber(source.temperatureC,-80,60),humidityPct=weatherNumber(source.humidityPct,0,100),windSpeedMs=weatherNumber(source.windSpeedMs,0,100),windDirectionDeg=weatherNumber(source.windDirectionDeg,0,360),observedAt=Date.parse(source.observedAt||source.forecastAt),precipitationMm=source.precipitationMm==null?null:weatherNumber(source.precipitationMm,0,1000),precipitationHours=source.precipitationHours==null?null:weatherNumber(source.precipitationHours,1,48);return temperatureC===null||humidityPct===null||windSpeedMs===null||windDirectionDeg===null||!Number.isFinite(observedAt)?null:{temperatureC,humidityPct,windSpeedMs,windDirectionDeg,forecastAt:new Date(observedAt).toISOString(),precipitationMm,precipitationHours}}
function windCompass(degrees){const points=['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];return points[Math.round(((Number(degrees)%360)+360)%360/22.5)%16]}
