function acceptRow(row){db=normalise(row.data);version=row.version;ready=true;syncText='Shared data · Up to date'}
function assignments(id){return db.teams.filter(t=>t.date===localDay()&&!t.closed&&t.members.includes(id))}
function assignmentConflicts(ids,date=localDay(),exclude=''){return db.teams.filter(t=>t.id!==exclude&&t.date===date&&!t.closed&&t.members.some(id=>ids.includes(id)))}
