function staffing(){const today=db.teams.filter(t=>t.date===localDay()),ids=new Set(today.filter(t=>!t.closed).flatMap(t=>t.members)),active=db.people.filter(p=>p.active);return {teams:today.length,assigned:ids.size,available:active.filter(p=>(p.availability||'ON_SITE')==='ON_SITE'&&!ids.has(p.id)).length,off:active.filter(p=>p.availability==='OFF').length,sick:active.filter(p=>p.availability==='SICK').length,active:active.length}}
function options(values,current='',all=''){const choices=[...new Set(values)];if(current&&!choices.includes(current))choices.unshift(current);return (all?'<option value="">'+esc(all)+'</option>':'')+choices.map(v=>'<option value="'+esc(v)+'" '+(v===current?'selected':'')+'>'+esc(v)+'</option>').join('')}
